      const metaValue=(key,value)=>({key,value,updatedAt:timestamp,deviceId}),meta=[metaValue('yearArchiveHistory',[...await ClassDB.getMeta('yearArchiveHistory',[]),{yearLabel:draft.oldYearLabel,passwordHint:draft.oldPasswordHint,archivedAt:timestamp}]),metaValue('activeYearId',newYear.id),metaValue('selectedClassId',newClass.id),metaValue('lastBackupAt',null),metaValue('backupDismissedUntil',null)];
      for(const [key,value] of Object.entries(carryValues))meta.push(metaValue(key,value));
